{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Imatinib had a mean absolute bioavailability of 98% in healthy subjects and patients, directly supporting high oral bioavailability at the F≥20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Brepocitinib absolute bioavailability was estimated at 75% in humans, directly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "GSK1322322 absolute bioavailability was 77% in fed healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brigatinib oral bioavailability was approximately 46% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tacrolimus oral bioavailability was approximately 20–25%, meeting the F≥20% threshold and supporting high oral bioavailability, though borderline.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Predicted human pharmacokinetics for compound 19 suggested 80% oral bioavailability, providing indirect supportive evidence.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All available experimental records report absolute or estimated oral bioavailability values ≥20% (20–98%), so the weight of evidence supports high bioavailability at the F≥20% threshold; confidence is tempered by lack of query-specific structural and direct data.",
  "evidence_gaps": [
    "No direct experimental measurement of oral bioavailability for the query molecule.",
    "Query structure and evidence-molecule structures are omitted, so structural similarity and transferability cannot be directly assessed.",
    "One record (C05) is borderline at 20–25% and one record (C06) is predicted rather than measured.",
    "Food effects and doses vary across records, but all reported values remain above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

